import data from'./geometry-data.js';import{spec}from'./dimensions.js';import{addStickers}from'./stickers.js';
class WhiteOled extends Display{constructor(options){super(options);this.material.fragmentShader=this.material.fragmentShader.replace('vec3 c = texture2D(map, (cell + 0.5) / res).rgb;','vec3 c = texture2D(map, (cell + 0.5) / res).rgb;\n  c = vec3(dot(c, vec3(0.2126, 0.7152, 0.0722)));');}}
class FixedRedLed extends Led{set(state){if(typeof state==='boolean')state={on:state};else if(typeof state==='string'||typeof state==='number')state={on:true};super.set({...state,color:spec.powerLed.color});}}
/** Deform only one original side tongue; retain every native triangle. */
class NativeSideButton extends Button{
 constructor(shell,sign){
  const hit=new THREE.Mesh(new THREE.PlaneGeometry(5,3.7),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));hit.name='TimerPWR native side tongue input surface';hit.position.z=.025;
  const face=sign<0?'left':'right';super({id:sign<0?'button-a':'button-b',label:sign<0?'Side button A':'Side button B',mesh:hit,position:[sign*12,spec.buttons.y,spec.buttons.z],quaternion:FACE[face],axis:[0,0,-1],travel:spec.buttons.travelMm,meta:{role:'visual-control',visualMotion:'native-flexure',surfaceFace:face,source:sign<0?'S1 BTN_A PA0':'S2 BTN_B PA4',travelSource:'0.22mm visual estimate; manufacturer rated travel unconfirmed',scope:'input intent only; does not edit OLED, timer, charge, light or power state'}});
  // Keep the input target at rest while the visible CAD surface flexes inward.
  this.object3d.add(hit);this.shell=shell;this.sign=sign;this.restPositions=shell.geometry.attributes.position.array.slice();this.restNormals=shell.geometry.attributes.normal.array.slice();this.weights=new Float32Array(this.restPositions.length/3);this.lastDepth=0;
  for(let i=0;i<this.weights.length;i++){const x=this.restPositions[i*3],y=this.restPositions[i*3+1],z=this.restPositions[i*3+2];if(x*sign>=10.299&&y>=3.21&&y<=8.79&&z>=-2.501&&z<=3.481)this.weights[i]=THREE.MathUtils.clamp((3.481-z)/5.981,0,1);}
  const index=shell.geometry.index.array,affected=new Set();for(let f=0;f<index.length;f+=3)if(this.weights[index[f]]||this.weights[index[f+1]]||this.weights[index[f+2]])for(let k=0;k<3;k++)affected.add(index[f+k]);
  this.normalVertices=Uint32Array.from(affected);this.normalMask=new Uint8Array(this.weights.length);for(const i of this.normalVertices)this.normalMask[i]=1;
  this.normalTriangles=[];for(let f=0;f<index.length;f+=3)if(this.normalMask[index[f]]||this.normalMask[index[f+1]]||this.normalMask[index[f+2]])this.normalTriangles.push(f);
  this.restNormalSums=new Float64Array(this.restPositions.length);this.currentNormalSums=new Float64Array(this.restPositions.length);this.scratch={from:new THREE.Vector3(),to:new THREE.Vector3(),normal:new THREE.Vector3(),rotation:new THREE.Quaternion()};this.sumLocalFaceNormals(this.restPositions,this.restNormalSums);this.meta.deformedNativeVertices=this.weights.filter(w=>w>0).length;
 }
 sumLocalFaceNormals(positions,target){target.fill(0);const index=this.shell.geometry.index.array;for(const f of this.normalTriangles){const a=index[f]*3,b=index[f+1]*3,c=index[f+2]*3,ux=positions[c]-positions[b],uy=positions[c+1]-positions[b+1],uz=positions[c+2]-positions[b+2],vx=positions[a]-positions[b],vy=positions[a+1]-positions[b+1],vz=positions[a+2]-positions[b+2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,l=Math.hypot(nx,ny,nz);if(!l)continue;for(let k=0;k<3;k++){const i=index[f+k];if(this.normalMask[i]){target[i*3]+=nx/l;target[i*3+1]+=ny/l;target[i*3+2]+=nz/l;}}}}
 syncNormals(depth){const a=this.shell.geometry.attributes.normal,{from,to,normal,rotation}=this.scratch;if(depth)this.sumLocalFaceNormals(this.shell.geometry.attributes.position.array,this.currentNormalSums);for(const i of this.normalVertices){const off=i*3;normal.fromArray(this.restNormals,off);if(depth){from.fromArray(this.restNormalSums,off);to.fromArray(this.currentNormalSums,off);if(from.lengthSq()>1e-20&&to.lengthSq()>1e-20){from.normalize();to.normalize();if(from.distanceToSquared(to)>1e-24)normal.applyQuaternion(rotation.setFromUnitVectors(from,to));}}a.setXYZ(i,normal.x,normal.y,normal.z);}a.needsUpdate=true;}
 update(dt){const changed=super.update(dt),depth=this.getActuationState().depthMm;if(depth!==this.lastDepth){const p=this.shell.geometry.attributes.position;for(let i=0;i<this.weights.length;i++)if(this.weights[i])p.setX(i,this.restPositions[i*3]-this.sign*depth*this.weights[i]);p.needsUpdate=true;this.syncNormals(depth);this.shell.geometry.computeBoundingBox();this.shell.geometry.computeBoundingSphere();this.lastDepth=depth;}return changed;}
 dispose(){this.shell=null;this.restPositions=null;this.restNormals=null;this.weights=null;this.normalVertices=null;this.normalMask=null;this.normalTriangles=null;this.restNormalSums=null;this.currentNormalSums=null;this.scratch=null;super.dispose();}
}
function pcb(host){const s=new THREE.Shape(),edge=10.1,top=18.2,bot=-18.4;s.moveTo(-edge,top);s.lineTo(edge,top);s.lineTo(edge,-4.4);s.lineTo(8,-4.4);s.absarc(8,-8,3.6,Math.PI/2,Math.PI*1.5,false);s.lineTo(edge,-11.6);s.lineTo(edge,bot);s.lineTo(5.35,bot);s.lineTo(5.35,-12.2);s.lineTo(-5.35,-12.2);s.lineTo(-5.35,bot);s.lineTo(-edge,bot);s.lineTo(-edge,-11.6);s.lineTo(-8,-11.6);s.absarc(-8,-8,3.6,-Math.PI/2,Math.PI/2,false);s.lineTo(-edge,-4.4);s.closePath();const hole=new THREE.Path();hole.absarc(0,-8,1.75,0,Math.PI*2,true);s.holes.push(hole);const board=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.8,bevelEnabled:false,curveSegments:40}),materials.plastic(0x234737,{roughness:.91}),[0,0,-3.8],'TimerPWR real-depth PCB with open mounting/Grove relief');board.userData={role:'physical-pcb',source:'Concealed outline inferred from exact native assembled shell and U189 drawing; no production placement/trace claim'};return board;}
function electronics(host){const chips=[],black=materials.plastic(0x232927,{roughness:.84}),tin=materials.metal(0xa7aaa3,{roughness:.58});for(const[n,x,y,w,h,t]of[['U6 STM32G031G8U6',-3.7,4.3,4,4,.8],['U2 INA3221',4.4,4.0,4.1,4.1,.8],['U8 LGS4056H',-4.5,13.2,4.9,3.9,.8],['U4 SY7088',4.3,-1.8,2.2,2.2,.6],['U5 MT9700',-.5,-1.8,2.6,2,.65],['U7 ME6206A33XG',-6.5,-1.5,2.1,1.4,.55],['U3 AW35122FDR',-4,9.7,1.1,1.1,.4],['U9 AW35122FDR',4,9.7,1.1,1.1,.4],['U1 TPS61040DBVR',6,13.1,2.8,1.6,.65],['Y1 32.768kHz crystal',0,1.5,3.1,1.5,.7]]){const c=mesh(host.body,new THREE.BoxGeometry(w,h,t),black,[x,y,-3+t/2],n+' physical package');c.userData={role:'concealed-electronic-package',placement:'Visual reconstruction only; schematic identity confirmed'};chips.push(c);if(w>=2)for(const side of[-1,1])for(let i=0;i<4;i++)mesh(host.body,new THREE.BoxGeometry(.5,.25,.16),tin,[x+side*(w/2+.16),y+(i-1.5)*h/4,-2.94],n+' solder land');}
 for(const[n,x,y,w,h]of[['L2 SY7088 boost inductor',4,-5,3,3],['L1 OLED boost inductor',6.7,9.6,2.5,2.5]])chips.push(mesh(host.body,new THREE.BoxGeometry(w,h,1.35),materials.plastic(0x50534c),[x,y,-2.325],n));for(let i=0;i<18;i++){const x=-7.7+(i%6)*2.7,y=-2+Math.floor(i/6)*2.2;mesh(host.body,new THREE.BoxGeometry(1.0,.55,.45),i%3?materials.plastic(0xbba67f):black,[x,y,-2.775],'TimerPWR concealed resistor/capacitor package');}return chips;}
function display(host){const p=spec.display.position;const backing=mesh(host.body,new THREE.BoxGeometry(15.5,13.4,1.05),materials.plastic(0x17221e,{roughness:.88}),[0,p[1],3.045],'TimerPWR OLED physical carrier backing');const glass=mesh(host.body,new THREE.BoxGeometry(14.4,11.5,1.4),materials.glossy(0x060a09,{roughness:.24}),[0,p[1],4.25],'TimerPWR OLED real glass stack and inactive edge');const flex=mesh(host.body,new THREE.BoxGeometry(8.4,4,.18),materials.plastic(0x996322),[0,2.2,2.65],'TimerPWR OLED concealed FPC tail');const lcd=host.add(new WhiteOled({id:'lcd',label:'0.66-inch white OLED · 64×48',width:64,height:48,size:spec.display.activeMm,style:'oled',position:p,glass:false,touch:false,offColor:0x060a09,blackLevel:0,meta:{role:'external-framebuffer',monochrome:true,emissionColor:'white',orientation:spec.display.orientation,nativeResolution:[64,48],monochromeMapping:'Luminance at render time; external source buffer preserved',scope:'Externally written pixels only; no firmware page, RTC, timer, power monitor, protocol or automatic values'}}));return{backing,glass,flex,lcd};}
function usb(host){const group=new THREE.Group();group.name='TimerPWR USB-C charging-only physical socket';group.position.fromArray(spec.usb.position);group.quaternion.copy(FACE.top);host.body.add(group);const metal=materials.metal(0xb8bdb8,{roughness:.4}),black=materials.plastic(0x141b19,{roughness:.7}),shape=capsule(8.6,2.85);shape.holes.push(capsule(8.0,2.25,{path:new THREE.Path(),clockwise:true}));mesh(group,new THREE.ExtrudeGeometry(shape,{depth:5.3,bevelEnabled:false,curveSegments:24}),metal,[0,0,-5.3],'TimerPWR USB-C real metal cavity shell');mesh(group,new THREE.BoxGeometry(7.9,2.15,.5),black,[0,0,-5.05],'TimerPWR USB-C rear insulator');mesh(group,new THREE.BoxGeometry(6.2,.6,3.5),black,[0,0,-2.3],'TimerPWR USB-C real insulating tongue');for(const sign of[-1,1])for(let i=0;i<6;i++)mesh(group,new THREE.BoxGeometry(.2,.06,1.7),materials.metal(0xc7af71,{roughness:.38}),[(i-2.5)*.75,sign*.33,-1.5],'TimerPWR USB-C tongue contact strip');const port=host.add(new Port({id:'usb',label:'USB-C · battery charge input only',connector:spec.usb.connector,position:spec.usb.position,quaternion:portQuaternion('top'),hitSize:[9,1,3],pins:['GND','VBUS','CC1','CC2'].map(name=>({name})),meta:{role:'visual-connector',face:'top',part:'TYPE-C 6P',usbData:false,powerRole:'battery-charging-input-only',requiresBatteryForGroveOutput:true,source:'Official U189 supply warning: USB only charges external battery and cannot directly supply Grove',scope:'Visual socket only; no charging, power forwarding, battery state, USB data or electrical behavior'}}));return{group,port};}
function battery(host){const g=new THREE.Group();g.name='TimerPWR MX1.25-2P external battery socket';g.position.fromArray(spec.battery.position);g.quaternion.copy(FACE.top);host.body.add(g);const white=materials.plastic(0xe5e4dc,{roughness:.7}),gold=materials.metal(0xb8b39d,{roughness:.5});for(const x of[-1.9,1.9])mesh(g,new THREE.BoxGeometry(.4,3.3,3.7),white,[x,0,-1.85],'TimerPWR battery socket side wall');for(const y of[-1.45,1.45])mesh(g,new THREE.BoxGeometry(3.4,.4,3.7),white,[0,y,-1.85],'TimerPWR battery socket edge guide');mesh(g,new THREE.BoxGeometry(3.4,2.5,.5),white,[0,0,-3.45],'TimerPWR battery connector rear insulator');for(const x of[-.625,.625])mesh(g,new THREE.BoxGeometry(.3,.3,2.4),gold,[x,-.15,-1.8],'TimerPWR battery1.25mm contact');const port=host.add(new Port({id:'battery',label:'External battery · 1.25mm 2P',connector:spec.battery.connector,position:spec.battery.position,quaternion:portQuaternion('top'),hitSize:[4.3,1,3.55],pins:[{name:'BAT+'},{name:'GND'}],meta:{role:'visual-connector',face:'top',pitchMm:1.25,physicalPinNumbering:'Not asserted; polarity follows exact printed label',scope:'Visual socket only; no battery or electrical model'}}));return{group:g,port};}
function grove(host){const g=connector(host.body,40,false,{height:5});g.position.z=-1.5;g.name='TimerPWR red open-top HY2.0-4P with four true contacts';const port=host.add(new Port({id:'grove',label:'PORT.A · I2C / externally modelled power output',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V_OUT',color:'red'},{n:3,name:'SDA',color:'yellow'},{n:4,name:'SCL',color:'white'}],meta:{role:'visual-connector',face:'bottom',protocol:'I2C',documentedAddress:'0x56',powerRole:'battery-boost-output; external framework only',usbDirectPowerForwarding:false,scope:'Mechanical attachment/cable pose only; no bus, supply, RTC, power forwarding or electrical behavior'}}));return{group:g,port};}
export function buildTimerPwr(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe6e7df,{roughness:.78})}),shell=parts['TimerPWR complete native assembled shell'];const board=pcb(host),chips=electronics(host),panel=display(host),usbSocket=usb(host),batterySocket=battery(host),groveSocket=grove(host),buttons=[host.add(new NativeSideButton(shell,-1)),host.add(new NativeSideButton(shell,1))];for(const sign of[-1,1]){const base=mesh(host.body,new THREE.BoxGeometry(1.25,3.8,2.4),materials.plastic(0x252d28),[sign*9.3,6,-.8],'TimerPWR S'+(sign<0?'1':'2')+' fixed tactile switch package');base.userData.role='fixed-switch-body';}
 const chip=new THREE.Mesh(new THREE.BoxGeometry(1.1,2.1,.55),materials.plastic(0xe1d4cf,{roughness:.52}));chip.name='TimerPWR D4 red indicator real package';const led=host.add(new FixedRedLed({id:'power-led',label:'Grove5V output indicator D4 · red',mesh:chip,position:spec.powerLed.position,color:spec.powerLed.color,radius:.28,glowSize:2.7,meta:{role:'externally-driven-visual',colorMode:'fixed-red',part:'D4',source:'U189 original schematic5V_OUT → R6 → D4 → GND; official4.webp red LED icon',documentationConflict:'Product pin-map calls PB4 charging LED; schematic identifies PB4 BAT_CHRG input independently of D4',scope:'External appearance only; no automatic charge, output power or battery response'}}));
 screw(host.body,[0,-8,-5.42],'back',1.65);addStickers(host);host.add(new Component({id:'sensor',label:'TimerPWR visual anchor',meta:{role:'visual-anchor',sku:'U189',scope:'No RTC, timing, INA3221 values, charging, battery, power cutoff, protocol or electrical simulation'}}));host.timerPwrAssembly={shell,board,chips,panel,usb:usbSocket,battery:batterySocket,grove:groveSocket,buttons,led};}
